<script>
(()=>{const csrf=<?=json_encode((string)$_SESSION['fne_lookup_csrf'])?>,form=document.getElementById('fneLookupForm'),error=document.getElementById('fneLookupError'),result=document.getElementById('fneLookupResult'),drop=document.getElementById('pdfDrop'),fileInput=document.getElementById('pdfFile'),progress=document.getElementById('pdfProgress'),analysis=document.getElementById('pdfAnalysis'),candidateList=document.getElementById('candidateList');
const esc=value=>String(value??'—').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));const showError=message=>{error.textContent=message;error.classList.remove('hidden');error.scrollIntoView({behavior:'smooth',block:'center'})};
async function verify(code,type='verificationCode'){error.classList.add('hidden');result.classList.add('hidden');progress.classList.remove('hidden');progress.querySelector('span').textContent='Interrogation sécurisée de la DGI…';try{const response=await fetch('api/fne_lookup.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({code,code_type:type})}),json=await response.json();if(!json.ok)throw Error(json.error||'Vérification impossible.');const data=json.data,invoice=data.invoice||{};document.getElementById('fneLookupMeta').textContent=`Réponse DGI HTTP ${data.http_status} · identifiant ${data.lookup_code_masked}`;const labels={invoice_number:'Numéro FNE',verification_code:'Code de vérification',invoice_date:'Date',total_amount:'Montant total',client_name:'Client',client_ncc:'NCC client',payment_method:'Mode de paiement',currency:'Devise'};document.getElementById('fneLookupFields').innerHTML=Object.entries(labels).map(([key,label])=>`<div class="rounded-2xl border border-emerald-100 bg-emerald-50/50 p-4"><dt class="text-xs font-black uppercase tracking-wider text-emerald-700">${esc(label)}</dt><dd class="mt-2 font-bold text-slate-950">${esc(invoice[key])}</dd></div>`).join('');document.getElementById('fneLookupRaw').textContent=JSON.stringify(data.raw_data,null,2);result.classList.remove('hidden');result.scrollIntoView({behavior:'smooth',block:'start'})}catch(ex){showError(ex.message)}finally{progress.classList.add('hidden')}}
function qrCandidate(raw){raw=String(raw||'').trim();const uuid=raw.match(/[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/i);if(uuid)return{value:uuid[0],type:'verificationCode',source:'QR Code'};try{const url=new URL(raw);for(const key of['verificationCode','verification_code','uuid','id']){const value=url.searchParams.get(key);if(value)return{value,type:'verificationCode',source:'QR Code'}}}catch(e){}if(/^[A-Za-z0-9._:\/-]{8,180}$/.test(raw))return{value:raw,type:'verificationCode',source:'QR Code'};return null}
async function scanImages(images){const found=[];if(!('BarcodeDetector'in window))return found;try{const formats=await BarcodeDetector.getSupportedFormats();if(!formats.includes('qr_code'))return found;const detector=new BarcodeDetector({formats:['qr_code']});for(const source of images){const image=new Image();image.src=source;await image.decode();for(const barcode of await detector.detect(image)){const candidate=qrCandidate(barcode.rawValue);if(candidate)found.push(candidate)}}}catch(e){}return found}
function renderCandidates(candidates){const unique=[...new Map(candidates.map(item=>[item.type+'|'+item.value,item])).values()];candidateList.innerHTML='';unique.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.className='flex items-center justify-between gap-3 rounded-2xl border border-indigo-100 bg-indigo-50/50 p-4 text-left transition hover:border-indigo-400 hover:bg-indigo-50';button.innerHTML=`<span class="min-w-0"><small class="block font-black uppercase tracking-wider text-indigo-600">${esc(item.source)} · ${item.type==='invoiceNumber'?'Numéro facture':'Code / UUID'}</small><strong class="mt-1 block truncate font-mono text-slate-950">${esc(item.value)}</strong></span><i class="fas fa-arrow-right text-indigo-700"></i>`;button.onclick=()=>{document.getElementById('fneCode').value=item.value;document.getElementById('fneCodeType').value=item.type;verify(item.value,item.type)};candidateList.appendChild(button);if(index===0){document.getElementById('fneCode').value=item.value;document.getElementById('fneCodeType').value=item.type}});return unique}
async function analyse(file){if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){showError('Sélectionnez une facture au format PDF.');return}error.classList.add('hidden');result.classList.add('hidden');analysis.classList.add('hidden');progress.classList.remove('hidden');progress.querySelector('span').textContent='Extraction du texte et préparation du QR…';try{const body=new FormData();body.append('invoice_pdf',file);const response=await fetch('api/fne_pdf_extract.php',{method:'POST',headers:{'X-CSRF-Token':csrf},body}),json=await response.json();if(!json.ok)throw Error(json.error||'Analyse PDF impossible.');const data=json.data;progress.querySelector('span').textContent='Recherche du QR Code dans les pages…';const qr=await scanImages(data.page_images||[]),candidates=renderCandidates([...(qr||[]),...(data.candidates||[])]);document.getElementById('pdfName').textContent=data.file_name;document.getElementById('pdfMeta').textContent=`${data.page_count_preview} page(s) inspectée(s) · ${data.text_detected?'texte PDF détecté':'document probablement scanné'}`;document.getElementById('pdfText').textContent=data.text_preview||'Aucun texte directement extractible.';const badge=document.getElementById('pdfBadge');badge.textContent=candidates.length?`${candidates.length} identifiant(s) détecté(s)`:'Identifiant non détecté';badge.className=candidates.length?'rounded-full bg-emerald-50 px-4 py-2 text-sm font-bold text-emerald-800':'rounded-full bg-amber-50 px-4 py-2 text-sm font-bold text-amber-800';if(!candidates.length)candidateList.innerHTML='<div class="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900 md:col-span-2">Le PDF ne contient pas de texte exploitable et le navigateur n’a pas détecté le QR. Saisissez le code dans le contrôle manuel ci-dessous.</div>';analysis.classList.remove('hidden');const trusted=candidates.find(item=>item.source==='QR Code')||(candidates.length===1?candidates[0]:null);if(trusted)await verify(trusted.value,trusted.type)}catch(ex){showError(ex.message)}finally{progress.classList.add('hidden')}}
drop.addEventListener('click',()=>fileInput.click());fileInput.addEventListener('change',()=>analyse(fileInput.files[0]));['dragenter','dragover'].forEach(name=>drop.addEventListener(name,event=>{event.preventDefault();drop.classList.add('border-indigo-600','bg-indigo-50')}));['dragleave','drop'].forEach(name=>drop.addEventListener(name,event=>{event.preventDefault();drop.classList.remove('border-indigo-600','bg-indigo-50')}));drop.addEventListener('drop',event=>analyse(event.dataTransfer.files[0]));form.addEventListener('submit',event=>{event.preventDefault();verify(document.getElementById('fneCode').value.trim(),document.getElementById('fneCodeType').value)})})();
</script>
